    game.darkEssencePerSecond = game.darkEssencePerSecond.mul(game.oganessonUpgradesBought[6] ** 1.2 * 2 + 1);
    if (game.unlockedAchievements[24] > 3) game.darkEssencePerSecond = game.darkEssencePerSecond.mul(5);
