//Large update (occurs once per second)
export function updateLarge(g: Engine) {
  const game = g.state;
  if (g.rt.timeStopped) return;
  g.rt.timeDivider = Math.max(1000 / (g.now() - g.rt.timeSinceLastUpdate), 0.0001);

  //Adds to the user's gold
  if (game.unlocks < 35 || game.nuclearPastaUpgradesBought[3] || game.nuclearPastaState != 2 && game.nuclearPastaState != 5) game.gold = game.gold.add(game.goldPerSecond.div(g.rt.timeDivider));
  //Adds to the user's fire
  if (game.unlocks >= 1) game.fire = game.fire.add(game.firePerSecond.div(g.rt.timeDivider));
  //Auto maxes all if the upgrade is bought
  if (game.unlockedAchievements[6] > 2 && game.fireAutoMaxAll) fireMaxAll(g);

  //Handles the platinum convert button cooldown
  if (game.platinumConvertCooldown > 0) {
    game.platinumConvertCooldown -= 0.5;
  }
  if (game.platinumUpgradesBought[4] == 1) game.platinum = game.platinum.add(game.platinumToGet.div(g.rt.timeDivider));
  if (game.unlocks >= 3) game.platinum = game.platinum.add(Decimal.max(game.bestPlatinumToGet.div(20), 2));

  //Handles the uranium convert button cooldown
  if (game.uraniumConvertCooldown > 0) {
    game.uraniumConvertCooldown -= 0.5;
  }
  if (game.unlocks >= 7) game.uranium = game.uranium.add(Decimal.max(game.bestUraniumToGet.div(20), 1));

  //Handles the dragon time spending cooldown
  if (game.dragonTimeCooldown > 0) {
    game.dragonTimeCooldown -= 0.5;
  }
  if (game.unlockedAchievements[6] > 0) {
    dragonSpendTime(g);
  }
  if (game.unlockedAchievements[10] > 0) {
    dragonFeed(g);
  }

  //Handles the plutonium convert button cooldown
  if (game.plutoniumConvertCooldown > 0) {
    game.plutoniumConvertCooldown -= 0.5;
  }
  if (game.unlocks >= 20) game.plutonium = game.plutonium.add(Decimal.max(game.bestPlutoniumToGet.div(20), 0));
  if (game.unlockedAchievements[3] > 7) {
    game.magic = game.magic.add(game.magicToGet.div(g.rt.timeDivider));
  } else if (game.unlockedAchievements[3] > 5) {
    game.magic = game.magic.add(game.magicToGet.div(100));
  }
  g.rt.magicHardcap = new Decimal("e5000000");
  if (game.tomeUpgradesBought[8] == true) g.rt.magicHardcap = g.rt.magicHardcap.pow(game.blueFireUpgradesBought[3].pow(0.7).mul(5).add(1));
  if (game.magic.gt(g.rt.magicHardcap)) {
    game.magic = g.rt.magicHardcap;
  }
  if (game.unlocks >= 10) game.cyanSigilPower = game.cyanSigilPower.add(game.cyanSigilPowerPerSecond.div(g.rt.timeDivider));
  if (game.unlocks >= 11) game.blueSigilPower = game.blueSigilPower.add(game.blueSigilPowerPerSecond.div(g.rt.timeDivider));
  if (game.unlocks >= 12) game.indigoSigilPower = game.indigoSigilPower.add(game.indigoSigilPowerPerSecond.div(g.rt.timeDivider));
  if (game.unlocks >= 13) game.violetSigilPower = game.violetSigilPower.add(game.violetSigilPowerPerSecond.div(g.rt.timeDivider));
  if (game.unlocks >= 14) game.pinkSigilPower = game.pinkSigilPower.add(game.pinkSigilPowerPerSecond.div(g.rt.timeDivider));
  if (game.unlocks >= 17) game.blueFire = game.blueFire.add(game.blueFirePerSecond.div(g.rt.timeDivider));
  if (game.unlocks >= 18) game.blood = game.blood.add(game.bloodPerSecond.div(g.rt.timeDivider));
  if (game.unlocks >= 21) game.redSigilPower = game.redSigilPower.add(game.redSigilPowerPerSecond.div(g.rt.timeDivider));
  if (game.unlocks >= 22) game.orangeSigilPower = game.orangeSigilPower.add(game.orangeSigilPowerPerSecond.div(g.rt.timeDivider));
  if (game.unlocks >= 23) game.yellowSigilPower = game.yellowSigilPower.add(game.yellowSigilPowerPerSecond.div(g.rt.timeDivider));
  if (game.unlocks >= 26 && game.holyTetrahedronUpgradesBought[11]) game.holyFire = game.holyFire.add(game.holyFirePerSecond.div(g.rt.timeDivider));
  if (game.holyOctahedronUpgradesBought[4]) game.holyTetrahedrons = game.holyTetrahedrons.add(0.5);
  if (game.unlocks >= 31) game.cosmicPlague = game.cosmicPlague.add(game.cosmicPlaguePerSecond.div(g.rt.timeDivider));
  if (game.unlocks >= 33) {
    game.lightEssence = game.lightEssence.add(game.lightEssencePerSecond.div(g.rt.timeDivider));
    game.darkEssence = game.darkEssence.add(game.darkEssencePerSecond.div(g.rt.timeDivider));
  }
  if (game.unlocks >= 34) game.deathEssence = game.deathEssence.add(game.deathEssencePerSecond.div(g.rt.timeDivider));
  if (game.unlocks >= 36) game.finalityEssence = game.finalityEssence.add(game.finalityEssencePerSecond.div(g.rt.timeDivider));
  if (game.unlockedAchievements[5] > 3) game.uranium = game.uranium.add(game.uraniumToGet.div(g.rt.timeDivider));
  if (game.unlockedAchievements[15] > 3) game.plutonium = game.plutonium.add(game.plutoniumToGet.div(g.rt.timeDivider));
  game.oganesson = game.oganesson.add(game.oganessonPerSecond.div(g.rt.timeDivider));
  if (game.unlockedAchievements[0] > 8 && game.minerAutoBuyMax) buyMaxMiners(g);
  if (game.unlockedAchievements[13] > 0) {
    game.cyanSigils = game.cyanSigils.add(game.cyanSigilsToGet.div(20));
    game.blueSigils = game.blueSigils.add(game.blueSigilsToGet.div(20));
    game.indigoSigils = game.indigoSigils.add(game.indigoSigilsToGet.div(20));
    game.violetSigils = game.violetSigils.add(game.violetSigilsToGet.div(20));
    game.pinkSigils = game.pinkSigils.add(game.pinkSigilsToGet.div(20));
  }
  if (game.unlockedAchievements[15] > 0) {
    g.rt.idealTradeLevel = game.cyanSigils.div(500000).log10().div(0.178);
    g.rt.knowledgeRewardTemp = new Decimal(1.5).pow(g.rt.idealTradeLevel.sub(1));
    g.rt.knowledgeRewardTemp = g.rt.knowledgeRewardTemp.mul(new Decimal(2).pow(game.knowledgeUpgradesBought[0].pow(0.5)));
    if (game.tomeUpgradesBought[2] == true) g.rt.knowledgeRewardTemp = g.rt.knowledgeRewardTemp.mul(2);
    if (game.tomeUpgradesBought[6] == true) g.rt.knowledgeRewardTemp = g.rt.knowledgeRewardTemp.mul(game.totalTomes.pow(1.2).add(1));
    if (game.tomeUpgradesBought[8] == true) g.rt.knowledgeRewardTemp = g.rt.knowledgeRewardTemp.mul(new Decimal(1000).pow(game.blueFireUpgradesBought[5].pow(0.6)));
    if (game.holyTetrahedronUpgradesBought[7]) g.rt.knowledgeRewardTemp = g.rt.knowledgeRewardTemp.mul(1e150);
    if (game.holyOctahedronUpgradesBought[8]) g.rt.knowledgeRewardTemp = g.rt.knowledgeRewardTemp.mul("e550");
    if (game.voidMagicUpgradesBought[11] == true) g.rt.knowledgeRewardTemp = g.rt.knowledgeRewardTemp.mul("e12000");
    if (game.unlocks >= 33 && game.darkEssenceUpgradesBought[2].gt(0)) g.rt.knowledgeRewardTemp = g.rt.knowledgeRewardTemp.mul(new Decimal(10).pow(new Decimal(2).pow(game.darkEssenceUpgradesBought[2].pow(0.5)).mul(5e9)));
    g.rt.knowledgeRewardTemp = g.rt.knowledgeRewardTemp.div(2).floor();
    game.knowledge = game.knowledge.add(g.rt.knowledgeRewardTemp);
    if (game.knowledge.gte(game.highestKnowledge)) game.highestKnowledge = game.knowledge;
  }
  if (game.unlockedAchievements[23] > 2) {
    game.redSigils = game.redSigils.add(game.redSigilsToGet.div(g.rt.timeDivider));
    game.orangeSigils = game.orangeSigils.add(game.orangeSigilsToGet.div(g.rt.timeDivider));
    game.yellowSigils = game.yellowSigils.add(game.yellowSigilsToGet.div(g.rt.timeDivider));
  }
  if (game.unlockedAchievements[13] > 4 && game.blueFireAutoMaxAll) blueFireMaxAll(g);
  if (game.unlockedAchievements[11] > 7 && game.knowledgeAutoMaxAll) knowledgeMaxAll(g);
  if (game.unlockedAchievements[14] > 1) buyMaxTomes(g);
  if (game.unlockedAchievements[21] > 7 && game.holyFireAutoMaxAll) holyFireMaxAll(g);
  if (game.unlockedAchievements[24] > 5 && game.plagueAutoMaxAll) plagueMaxAll(g);
  if (game.unlockedAchievements[24] > 2) planetBuyMax(g);
  if (game.unlocks == 29 && game.gold.gte("e1e5000")) {
    addUnlock(g); //sets unlock to 30
  }
  if (game.unlockedAchievements[24] > 0) {
    game.holyTetrahedrons = game.holyTetrahedrons.add(game.holyTetrahedronsToGet.div(g.rt.timeDivider));
    game.holyOctahedrons = game.holyOctahedrons.add(game.holyOctahedronsToGet.div(g.rt.timeDivider));
    game.holyDodecahedrons = game.holyDodecahedrons.add(game.holyDodecahedronsToGet.div(g.rt.timeDivider));
  }
  if (game.unlockedAchievements[24] > 9) gainMaxPasta(g);
  if (game.unlocks >= 35) {
    game.nuclearPastaCooldown -= 0.5;
    if (game.nuclearPastaCooldown == 0) {
      game.nuclearPastaCooldown = 30;
      setNuclearPastaState(g);
      game.nuclearPastaExtended = false;
    }
  }
  updateSmall(g);
  checkAchievements(g);
  if (game.sigilResetterActive) sigilAutoResetter(g);
  if (game.unlockedAchievements[20] > 0) {
    maxAllSigilUpgrades(g);
    maxRedSigilUpgrades(g);
    maxOrangeSigilUpgrades(g);
    maxYellowSigilUpgrades(g);
  }
  if (!g.rt.isDevVersion) {}
  g.rt.timeSinceLastUpdate = g.now();
}
export function toggleConfirmations(g: Engine, x) {
  const game = g.state;
  if (x == 1) {
    if (game.confirmations[0]) {
      game.confirmations[0] = false;
    } else {
      game.confirmations[0] = true;
    }
  } else if (x == 2) {
    if (game.confirmations[1]) {
      game.confirmations[1] = false;
    } else {
      game.confirmations[1] = true;
    }
  } else if (x == 3) {
    if (game.confirmations[2]) {
      game.confirmations[2] = false;
    } else {
      game.confirmations[2] = true;
    }
  }
}
export function changeBackgroundPattern(g: Engine) {
  const game = g.state;
  if (game.backgroundPatternOn) {
    game.backgroundPatternOn = false;
  } else {
    game.backgroundPatternOn = true;
  }
}
export function addUnlock(g: Engine, x = 1) {
  const game = g.state;
  game.unlocks += x;
  let newAch = false;
  for (let i = 0; i < achievementDisplayUnlocks[game.unlocks].length; i++) {
    if (achievementDisplayUnlocks[game.unlocks][i] > achievementDisplayUnlocks[game.unlocks - x][i]) {
      newAch = true;
      break;
    }
  }
  if (newAch) {
    showAchievements(g, game.unlocks);
    achievementTabFlash(g);
  }
}
export function timePlayedUp(g: Engine) {
  const game = g.state;
  if (g.rt.bigFinishPoint == 0) {
    g.rt.timePlayedDiff = (g.now() - g.rt.lastTimePlayedUp) / 1000;
    game.timePlayed += g.rt.timePlayedDiff;
    g.rt.timePlayedFloor = Math.floor(game.timePlayed);
    g.rt.timePlayedHours = Math.floor(g.rt.timePlayedFloor / 3600);
    g.rt.timePlayedMinutes = Math.floor(g.rt.timePlayedFloor / 60) % 60;
    g.rt.timePlayedSeconds = g.rt.timePlayedFloor % 60;
    g.rt.timeString = g.rt.timePlayedHours + ":" + ((g.rt.timePlayedMinutes < 10 ? '0' : '') + g.rt.timePlayedMinutes) + ":" + ((g.rt.timePlayedSeconds < 10 ? '0' : '') + g.rt.timePlayedSeconds);
    g.rt.lastTimePlayedUp = g.now();
  }
}
//The big finale (saving this for later)
export function bigFinishCheck(g: Engine) {
  const game = g.state;
  if (game.gold.gte("ee1e12")) bigFinish(g);
}
export function bigFinish(g: Engine) {
  const game = g.state;
  if (g.rt.bigFinishPoint == 0) {
    "none";
    game.dragonStage = 11;
    g.rt.timePlayedFloor = Math.floor(game.timePlayed);
    g.rt.timePlayedHours = Math.floor(g.rt.timePlayedFloor / 3600);
    g.rt.timePlayedMinutes = Math.floor(g.rt.timePlayedFloor / 60) % 60;
    g.rt.timePlayedSeconds = g.rt.timePlayedFloor % 60;
    g.rt.timeString = g.rt.timePlayedHours + ":" + ((g.rt.timePlayedMinutes < 10 ? '0' : '') + g.rt.timePlayedMinutes) + ":" + ((g.rt.timePlayedSeconds < 10 ? '0' : '') + g.rt.timePlayedSeconds);
  }
  if (g.rt.bigFinishPoint >= 47) {
    return;
  }
  g.rt.bigFinishPoint++;
}
